ALTER PROCEDURE [MonitoringDeliverables].[DeleteAllDeliverablePeriodsForAllocation]
    @allocationNumber [nvarchar](20)
AS
BEGIN
      DELETE 
    FROM AllocationDeliverablePeriod 
    	                        WHERE 
    		                        ContractAllocationNumber = @allocationNumber
    
    	                        SELECT @@ROWCOUNT
END
